"""
This module provides functionality related to Egate telnet console.

Classes:
- :class:`EgateConsole`: Streamlines sending commands to the EgateConsole.
"""

from taf.internal.managedobject import ManagedObject
from .exceptions import EgateConsoleSetupFailure
from . import logger
from socket import timeout as timeout_exc
from pyte import Stream, Screen
import re


class VTEmuDecoder(object):
    """ A basic implementation of decoder for EgateConsole output.

    This uses pyte library to emulate a virtual terminal, so that the ANSII
    sequences are parsed.
    """
    EGATE_SCREEN_WIDTH = 80

    def decode(self, data):
        """
        decode output from egate,remove extraneous ASCII code.
        :param data: output of egate console
        :return: pure string type without ASCII code.
        """
        data = data.decode()
        no_lines = data.count('\n')
        screen = Screen(self.EGATE_SCREEN_WIDTH, no_lines)
        stream = Stream(screen)

        stream.feed(data)
        return '\n'.join(screen.display)

    def crtlch_removal(self, data):
        mpa = dict.fromkeys(range(32))
        outputs = data.decode().split("\n")
        output = "\n".join([i.encode("ascii", "ignore").decode().replace("\x1b[K", "").translate(mpa) for i in outputs])
        cleaned = re.sub('\[[0-9;]+[a-zA-Z]', ' ', output)
        return cleaned


class EgateConsole(ManagedObject):
    """ This class wraps around Egate telnet session and automates sending
    commands to it / receiving the output from it.

    Methods:
    - :meth:`execute`: send a command to egate console, await prompt and return
    output.
    - :meth:`setup`: connect to the Egate console, wait for prompt. If waiting
    for prompt times out (takes longer than setup_timeout specified in init),
    EgateConsoleSetupFailure is raised.
    """
    PROMPT = "EGATE>"
    DEFAULT_DECODER = VTEmuDecoder

    # TODO: Add method docstrings

    def __init__(self, telnet_session, edaemon, egate, setup_timeout=5.0,
                 *args, **kwargs):
        """
        init a egate console project
        :param telnet_session: a telnet object, created by telnet.Telnet()
        :param edaemon: an edaemon object
                        created by software_components.edamemon()
        :param egate:  an egate object
                       created by software_components.egate()
        :param setup_timeout: set timeout for set egate console,
                              default is 5 seconds.
        """
        super(EgateConsole, self).__init__(**kwargs)
        self.add_prerequisite(edaemon)
        self.add_prerequisite(egate)
        self.add_prerequisite(telnet_session)

        self.logger = logger.getChild(self.__class__.__name__)
        self._telnet_session = telnet_session
        self._setup_timeout = setup_timeout
        self.decoder = self.DEFAULT_DECODER()

    def _setup(self):
        if not self._client_is_on_prompt(self._setup_timeout):
            exc_msg = "Timed out while waiting for the first console prompt."
            raise EgateConsoleSetupFailure(exc_msg)
        else:
            self.logger.info("EgateConsole connection setup done. Using CRTL character removal decoding.")

    def _client_is_on_prompt(self, timeout):
        try:
            self.read_until_prompt(timeout)
        except timeout_exc:
            return False
        return True

    def _log_output(self, output):
        """
        log input into robot debug level log information
        :param output: a string output from egate console
        """
        self.logger.debug("Egate output:")
        self.logger.debug(output)

    def read_output(self, filter=None):
        """
        read current egate console outputs
        Returns empty string if EOF is hit. Blocks if no data is immediately
        available.
        filter output before return if filter is given.
        :param filter: a function filter specific contents.
        :return: string type console output
        """
        output = self._telnet_session.read_some()
        output = self.decoder.crtlch_removal(output)
        self._log_output(output)
        if filter is not None:
            output = filter(output)
        logger.info(output)
        return output

    def read_output_until(self, expected, timeout=None, filter=None):
        """
        read egate output until match the expected string or reach the timeout

        :param expected: a string going to be found in output
        :param timeout: max read time, specified in second
        :param filter: a function filter specific contents.
        :return: string type console output
        """
        self._log_reading_until("Reading output until \"{expected}\".",
                                expected, timeout)

        output = self._read_until(expected, timeout)
        if filter is not None:
            output = filter(output)
        logger.info(output)
        return output

    def read_output_until_re(self, expected, timeout=None, filter=None):
        """
        read egate output until match the expected regular expression
        or reach the timeout

        :param expected: a regular expression
        :param timeout: max read time, specified in second
        :param filter: a function filter specific contents.
        :return: string type console output
        """
        self._log_reading_until("Reading until match re\"{expected}\".",
                                expected, timeout)

        output = self._read_until_re(expected, timeout)
        if filter is not None:
            output = filter(output)
        logger.info(output)
        return output

    def read_until_prompt(self, timeout=None, filter=None):
        """
        keep reading until reach the timeout and return the output
        :param timeout: max read time, specified in second
        :param filter: a function filter specific contents.
        :return: string type console output
        """
        self._log_reading_until("Reading until prompt (\"{expected}\").",
                                self.PROMPT, timeout)

        output = self._read_until(self.PROMPT, timeout)
        output = self._remove_prompt_from_output(output)
        if filter is not None:
            output = filter(output)
        logger.info(output)

        return output

    def _log_reading_until(self, log_msg, expected, timeout):
        """
        log expected target / timeout into robot log file.
        """
        if timeout is not None:
            log_msg += " Timeout: {timeout} seconds."
        log_msg = log_msg.format(expected=expected, timeout=timeout)
        self.logger.debug(log_msg)

    def _remove_prompt_from_output(self, output):
        return output.replace(self.PROMPT, '')

    def _read_until(self, expected, timeout):
        output = self._telnet_session.read_until(expected.encode(), timeout)
        output = self.decoder.crtlch_removal(output)
        self._log_output(output)
        if expected not in output and timeout is not None:
            raise timeout_exc('read timed out.')

        return output

    def _read_until_re(self, expected_re, timeout):
        re_list = [expected_re.encode()]
        output = self._telnet_session.expect(re_list, timeout)
        output = self.decoder.crtlch_removal(output[-1])
        self._log_output(output)
        expected = re.compile(expected_re)
        re_result = expected.search(output)
        if re_result is None and timeout is not None:
            raise timeout_exc('read timed out.')

        return output

    def execute(self, command, timeout=None):
        """
        execute command in egate console.
        :param command: the string type command
        """
        self.logger.info("Sending \"{}\" to egate console.".format(command))

        command = command + '\n'
        self._telnet_session.write(command.encode())

    def _teardown(self):
        self.execute('exit')

    def configure(self, file):
        """
        set cfg file in egate console
        :param file: the name of config file
        :return: no return
        """
        configure_cmd = self._generate_configure_cmd(file=file)
        return self.execute(configure_cmd)

    @staticmethod
    def _generate_configure_cmd(**cmd_args):
        """
        generate cfg command with file name.
        :param cmd_args: file name
        :return: the string type cfg command.
        """
        cmd_template = 'cfg file={file}'
        return cmd_template.format(**cmd_args)
